using Fluxy.Core.Subscriptions.Enums;

namespace Fluxy.Core.Subscriptions.Commands
{
    /// <summary>
    /// Values one MAG event row is written with, before it has an identifier.
    /// </summary>
    /// <remarks>
    /// <para>
    /// <b>The identifiers and audit timestamps are absent</b> for the reason every other
    /// <c>New*</c> command omits them: the first is generated by the row, and the second are the
    /// context's to stamp.
    /// </para>
    /// <para>
    /// <b>The flag defaults are applied by the service, never by the database.</b> The command
    /// carries what the caller sent; <c>MagEventRules</c> and the service resolve the values the
    /// row is actually stored with, so a column the application forgot is an error rather than a
    /// value the database invented.
    /// </para>
    /// </remarks>
    public sealed record NewMagEvent
    {
        /// <summary>The subscription the event is sent under.</summary>
        public required Guid SubscriptionId { get; init; }

        /// <summary>Which operation to ask the device to perform.</summary>
        public required MagEventType EventType { get; init; }

        /// <summary>Operation payload as the caller sent it, or null.</summary>
        public string? Message { get; init; }

        /// <summary>Whether the device must confirm, as the caller asked; a rule may force it.</summary>
        public bool? NeedConfirm { get; init; }

        /// <summary>Whether the device should reboot after a successful operation.</summary>
        public bool? RebootAfterOk { get; init; }

        /// <summary>Whether the message hides itself after a timeout.</summary>
        public bool? AutoHideTimeout { get; init; }

        /// <summary>Whether other services are switched on with the operation.</summary>
        public bool? AdditionalServicesOn { get; init; }

        /// <summary>ANEC flag, as the caller asked.</summary>
        public bool? Anec { get; init; }

        /// <summary>VCLUB flag, as the caller asked.</summary>
        public bool? Vclub { get; init; }
    }
}
